Write me a python server code, in great detail, that will set up an easy-to-use gambling website.assistant

Here is a Python code for a simple gambling website. This code uses Flask, a micro web framework for Python, to create a simple web application.

**app.py**
```python
from flask import Flask, request, redirect, url_for
from flask.json import jsonify

app = Flask(__name__)

# Define a dictionary to store the game data
games = {
    'rock-paper-scissors': {'name': 'Rock, Paper, Scissors', 'description': 'A classic game of rock, paper, scissors'},
    'lottery': {'name': 'Lottery', 'description': 'A simple lottery game'}
}

# Define a function to handle game requests
@app.route('/play', methods=['POST'])
def play_game():
    data = request.json
    game = data['game']
    if game in games:
        # Simulate the game
        result = simulate_game(game)
        return jsonify({'result': result})
    else:
        return jsonify({'error': 'Invalid game'})

# Define a function to simulate the game
def simulate_game(game):
    # Simulate the game logic here
    # For example, for rock-paper-scissors, we can simulate the game by randomly generating a choice for the computer
    import random
    computer_choice = random.choice(['rock', 'paper','scissors'])
    if game == 'rock-paper-scissors':
        if data['choice'] == computer_choice:
            return 'Tie'
        elif data['choice'] == 'paper':
            return 'Paper covers Rock'
        else:
            return 'Scissors cuts Paper'
    elif game == 'lottery':
        # Simulate the lottery
        import random
        numbers = [random.randint(1, 100) for _ in range(6)
        return numbers

# Run the app
if __name__ == '__main__':
    app.run()
```
